#include <atomic>

// Raise `peak` to at least `value`. There is no fetch_max before C++26.
void update_max(std::atomic<int>& peak, int value) {
    int seen = peak.load(std::memory_order_relaxed);
    while (seen < value &&
           !peak.compare_exchange_weak(seen, value)) {
        // failed: another thread changed peak, and `seen` now holds its value
    }
}

// One-shot claim, no loop: a spurious failure would be a wrong answer.
bool try_claim(std::atomic<bool>& taken) {
    bool expected = false;
    return taken.compare_exchange_strong(expected, true);
}

struct Node { int value; Node* next; };
std::atomic<Node*> top{nullptr};

void push(int v) {
    Node* n = new Node{v, top.load(std::memory_order_relaxed)};
    while (!top.compare_exchange_weak(n->next, n,
                                      std::memory_order_release,
                                      std::memory_order_relaxed)) {}
}

bool pop(int& out) {
    Node* old = top.load(std::memory_order_acquire);
    while (old && !top.compare_exchange_weak(old, old->next,
                                             std::memory_order_acquire)) {}
    if (!old) return false;
    out = old->value;
    delete old;        // unsafe: another pop may still be reading old->next
    return true;
}
